SELECT ?sensor ?tsid WHERE {
  ?zone a brick:Zone ; rdfs:label "Perimeter_mid_ZN_3" .
  ?sensor a brick:Electric_Power_Sensor ;
    brick:isAttachedTo ?zone ;
    brick:hasInputSignal brick:Electric_Power ;
    ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
  ?sensor brick:hasSubclassOf ?c .
}

SELECT ?s ?p ?o WHERE {
  ?s brick:isAttachedTo ?z .
  ?z rdfs:label ?lbl .
  FILTER(?lbl="Perimeter_mid_ZN_3")
  ?p ?o .
} LIMIT 40

SELECT ?z ?lbl WHERE {
  ?z a brick:Zone ; rdfs:label ?lbl .
  FILTER(CONTAINS(LCASE(?lbl), "perimeter_mid"))
}

SELECT ?z ?lbl WHERE {
  ?z a brick:Zone ; rdfs:label ?lbl .
} LIMIT 60

